script:
(function () {
  'use strict';
  // ---- Share insurance constant ----------------------------------------------------------
  // NCUA standard maximum share insurance amount: $250,000 per member per ownership category.
  // Source: ncua.gov/consumers/share-insurance-coverage (checked in this session, 2026).
  // Joint accounts: each co-owner's share of all joint accounts is covered up to $250,000.
  var NCUA_LIMIT = 250000;
  // ----------------------------------------------------------------------------------------
  // Share certificate dividends. Dividends accrue at the dividend rate r compounded n times a year;
  // after t years $1 left in the certificate is worth (1 + r/n)^(n t). They are credited every c
  // months: the credit is the growth since the last credit. If credited dividends are transferred
  // out, the certificate restarts from the opening deposit after every credit, so each full credit
  // pays P x ((1 + r/n)^(n c / 12) - 1). APY = (1 + r/n)^n - 1 (NCUA Part 707 Appendix A with a
  // 365-day term); an APY input is turned back into r = n x ((1 + APY)^(1/n) - 1).
  // Early closing after W months: dividends credited up to the last crediting date are kept (accrued,
  // uncredited dividends are assumed forfeited); penalty = P x r x penalty days / 365.
  // Verified (scratchpad cu5/tests/cuc.test.js): $25,000 at 4% compounded daily for 24 months =
  // $2,082.06 of dividends, APY 4.08%; monthly crediting transferred out = 24 x $25,000 x
  // ((1 + 0.04/365)^(365/12) - 1) = $2,003.23; 180-day penalty on $25,000 at 4% = $493.15;
  // insurance: $25,000 + $240,000 other shares + dividends over $250,000 shows the excess.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function pct(x, d) { return (x * 100).toFixed(d) + '%'; }

  // Value of $1 after `months` months left to compound.
  function factor(r, n, months) { return Math.pow(1 + r / n, n * months / 12); }

  function schedule(P, r, n, term, credit, payout) {
    var step = credit === 0 ? term : credit, rows = [], total = 0, last = 0;
    for (var m = step; last < term; m += step) {
      var at = Math.min(m, term), div;
      if (payout === 'out') div = P * (factor(r, n, at - last) - 1);
      else div = P * (factor(r, n, at) - factor(r, n, last));
      total += div;
      rows.push({ month: at, dividend: div, total: total, balance: payout === 'out' ? P : P + total });
      last = at;
    }
    return rows;
  }

  function clear() {
    ['cucDividends', 'cucBalance', 'cucRateOut', 'cucFirst', 'cucEarned', 'cucPenaltyOut', 'cucNet', 'cucTotalShares', 'cucLimit', 'cucUninsured'].forEach(function (id) { set(id, '–'); });
    ['cucFirstNote', 'cucEarlyNote', 'cucInsNote'].forEach(function (id) { set(id, ''); });
    document.getElementById('cucSchedule').innerHTML = '';
  }

  function update() {
    var P = num('cucDeposit'), rate = num('cucRate'), term = Math.round(num('cucTerm')), pen = num('cucPenalty'),
        close = Math.round(num('cucClose')), other = num('cucOther'),
        type = document.getElementById('cucRateType').value, payout = document.getElementById('cucPayout').value,
        n = parseInt(document.getElementById('cucCompound').value, 10), credit = parseInt(document.getElementById('cucCredit').value, 10),
        owners = parseInt(document.getElementById('cucOwners').value, 10);
    if (isNaN(other)) other = 0;
    var error = document.getElementById('cucError');
    var bad = [P, rate, term, pen, close, n, credit, owners].some(isNaN) || P < 0 || P > 1e10 || rate < 0 || rate > 100 ||
              term < 1 || term > 120 || pen < 0 || pen > 1825 || close < 1 || close > 120 || other < 0 || other > 1e10;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a deposit of $0 or more, a rate from 0 to 100%, a term of 1 to 120 months, a penalty of 0 to 1,825 days, a closing month from 1 to 120 and other shares of $0 or more.';
      clear();
      return;
    }
    var r = type === 'apy' ? n * (Math.pow(1 + rate / 100, 1 / n) - 1) : rate / 100;
    var apy = Math.pow(1 + r / n, n) - 1;
    var rows = schedule(P, r, n, term, credit, payout), total = rows[rows.length - 1].total;
    set('cucDividends', money.format(total));
    set('cucBalanceLabel', payout === 'out' ? 'Certificate at maturity (dividends paid out)' : 'Certificate at maturity');
    set('cucBalance', money.format(payout === 'out' ? P : P + total));
    set('cucRateOutLabel', type === 'apy' ? 'Dividend rate' : 'APY');
    set('cucRateOut', type === 'apy' ? pct(r, 3) : pct(apy, 2));
    set('cucFirst', money.format(rows[0].dividend));
    set('cucFirstNote', credit === 0 ? 'All dividends are credited when the certificate matures.' : 'Credited after month ' + rows[0].month + '; ' + rows.length + ' credits in all.');

    // Early withdrawal
    if (close >= term) {
      set('cucEarned', money.format(total));
      set('cucPenaltyOut', money.format(0));
      set('cucNet', money.format(P + total));
      set('cucEarlyNote', 'The certificate has matured by then, so no penalty applies.');
    } else {
      var kept = 0;
      rows.forEach(function (row) { if (row.month <= close) kept = row.total; });
      var penalty = P * r * pen / 365, net = P + kept - penalty;
      set('cucEarned', money.format(kept));
      set('cucPenaltyOut', money.format(penalty));
      set('cucNet', money.format(Math.max(0, net)));
      var note = 'Assumes the penalty is ' + pen + ' days of dividends on the whole deposit and that dividends accrued since the last credit are not paid.';
      if (net < P) note = 'The penalty is larger than the dividends credited, so ' + money.format(Math.min(P, P - net)) + ' comes out of your deposit. ' + note;
      set('cucEarlyNote', note);
    }

    // Share insurance
    var shares = P + total + other, limit = NCUA_LIMIT * owners, over = Math.max(0, shares - limit);
    set('cucTotalShares', money.format(shares));
    set('cucLimit', money.format(limit));
    set('cucUninsured', money.format(over));
    set('cucInsNote', over > 0 ? 'About ' + money.format(over) + ' would be above the NCUA limit at maturity. Spreading money across ownership categories or credit unions can keep it all covered.'
                               : 'Fully within the NCUA limit of ' + money.format(NCUA_LIMIT) + ' per member per ownership category. Check complex cases with NCUA\'s share insurance estimator.');

    document.getElementById('cucSchedule').innerHTML = rows.map(function (row) {
      return '<tr><td>' + row.month + '</td><td>' + money.format(row.dividend) + '</td><td>' + money.format(row.total) + '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cucForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
